import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { ChevronDown, LocateFixed, MapPin, Search, X } from "lucide-react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
} from "@/components/ui/dialog";
import { MapMenuMap, type GoogleMapPoint } from "@/components/ui/map-menu-map";
import { Input } from "@/components/ui/input";
import { useKrakstackLocale } from "@/components/ui/krakstack-provider";
import { cn } from "@/lib/utils";

export enum MapMenuMode {
  Point = "point",
  Radius = "radius",
}

export type MapMenuPoint = GoogleMapPoint;

export const mapMenuRadiiKm = [1, 2, 5, 10, 20, 40, 60, 80, 100, 250, 500] as const;

export type MapMenuLocation = {
  id: string;
  label: string;
  title?: string | undefined;
  details?: string | undefined;
  center: MapMenuPoint;
};

export type MapMenuMessages = {
  title: string;
  location: string;
  placeholder: string;
  clear: string;
  close: string;
  currentLocation: string;
  searchWithin: string;
  suggestions: string;
  loading: string;
  noResults: string;
  searchHint: string;
  ipNotice: string;
  browserNotice: string;
  radiusHint: string;
  cancel: string;
  confirm: string;
  confirmError: string;
};

type MapMenuCommonProps = {
  apiKey: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  input: string;
  onInputChange: (input: string) => void;
  selectedLocation: MapMenuLocation | null;
  suggestions: readonly MapMenuLocation[];
  onSelectLocation: (location: MapMenuLocation) => void;
  onUseCurrentLocation?: (() => void) | undefined;
  locating?: boolean | undefined;
  loadingSuggestions?: boolean | undefined;
  suggestionsError?: string | undefined;
  error?: string | undefined;
  provenance?: "ip" | "browser" | undefined;
  overlayColor?: string | undefined;
  className?: string | undefined;
  confirmClassName?: string | undefined;
  locale?: string | undefined;
  messages?: Partial<Record<string, Partial<MapMenuMessages>>> | undefined;
};

export type MapMenuProps = MapMenuCommonProps &
  (
    | {
        mode: MapMenuMode.Point;
        radiusKm?: never;
        onRadiusChange?: never;
        radiusOptions?: never;
        onConfirm: (selection: { location: MapMenuLocation }) => void | Promise<void>;
      }
    | {
        mode?: MapMenuMode.Radius | undefined;
        radiusKm: number;
        onRadiusChange: (radiusKm: number) => void;
        radiusOptions?: readonly number[] | undefined;
        onConfirm: (selection: {
          location: MapMenuLocation;
          radiusKm: number;
        }) => void | Promise<void>;
      }
  );

const defaultMessages = {
  en: {
    title: "Choose your location",
    location: "City or address",
    placeholder: "Search a city or address…",
    clear: "Clear location",
    close: "Close",
    currentLocation: "Use my location",
    searchWithin: "Search within",
    suggestions: "Location suggestions",
    loading: "Finding matching places…",
    noResults: "No matching places. Try a city or address.",
    searchHint: "Search for a place and choose a suggestion to preview it on the map.",
    ipNotice: "Using your approximate location from your IP address.",
    browserNotice: "Using your browser location.",
    radiusHint: "The circle shows your search area.",
    cancel: "Cancel",
    confirm: "Use this location",
    confirmError: "Your location could not be saved. Try again.",
  },
  fr: {
    title: "Choisir votre lieu",
    location: "Ville ou adresse",
    placeholder: "Rechercher une ville ou une adresse…",
    clear: "Effacer le lieu",
    close: "Fermer",
    currentLocation: "Utiliser ma position",
    searchWithin: "Rechercher dans un rayon de",
    suggestions: "Suggestions de lieux",
    loading: "Recherche de lieux…",
    noResults: "Aucun lieu correspondant. Essayez une ville ou une adresse.",
    searchHint: "Recherchez un lieu et choisissez une suggestion pour le voir sur la carte.",
    ipNotice: "Position approximative obtenue à partir de votre adresse IP.",
    browserNotice: "Position fournie par votre navigateur.",
    radiusHint: "Le cercle indique votre zone de recherche.",
    cancel: "Annuler",
    confirm: "Utiliser ce lieu",
    confirmError: "Votre lieu n’a pas pu être enregistré. Réessayez.",
  },
} satisfies Record<"en" | "fr", MapMenuMessages>;

/** Controlled picker: the host owns lookup, location acquisition and persisted state. */
export const MapMenu = (props: MapMenuProps) => {
  const {
    apiKey,
    open,
    onOpenChange,
    input,
    onInputChange,
    selectedLocation,
    suggestions: locationSuggestions,
    onSelectLocation,
    radiusKm,
    radiusOptions = mapMenuRadiiKm,
    onUseCurrentLocation,
    locating = false,
    loadingSuggestions = false,
    suggestionsError,
    error,
    provenance,
    overlayColor = "#f56476",
    className,
    confirmClassName,
    locale: localeOverride,
    messages,
  } = props;
  const radiusEnabled = props.mode !== MapMenuMode.Point;
  const locale = useKrakstackLocale(localeOverride);
  const suggestions = locationSuggestions.slice(0, 3);
  const baseLocale = locale.split("-")[0] ?? "en";
  const labels = {
    ...(baseLocale === "fr" ? defaultMessages.fr : defaultMessages.en),
    ...messages?.[baseLocale],
    ...messages?.[locale],
  };
  const id = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const popupRef = useRef<HTMLDivElement>(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [applying, setApplying] = useState(false);
  const [confirmFailed, setConfirmFailed] = useState(false);
  const selectedMatchesInput = selectedLocation?.label === input.trim();
  const notice =
    provenance === "ip"
      ? labels.ipNotice
      : provenance === "browser"
        ? labels.browserNotice
        : !selectedMatchesInput
          ? labels.searchHint
          : undefined;
  const markerIcon = `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="40" height="48" viewBox="0 0 40 48"><path d="M20 46s15-14.3 15-27A15 15 0 1 0 5 19c0 12.7 15 27 15 27Z" fill="${overlayColor}" stroke="white" stroke-width="3"/><circle cx="20" cy="19" r="6" fill="white"/></svg>`)}`;

  useEffect(() => {
    if (!open || !window.visualViewport) return;
    const viewport = window.visualViewport;
    const sync = () => {
      popupRef.current?.style.setProperty("--map-picker-height", `${viewport.height}px`);
      popupRef.current?.style.setProperty("--map-picker-top", `${viewport.offsetTop}px`);
    };
    sync();
    viewport.addEventListener("resize", sync);
    viewport.addEventListener("scroll", sync);
    return () => {
      viewport.removeEventListener("resize", sync);
      viewport.removeEventListener("scroll", sync);
    };
  }, [open]);

  useEffect(() => {
    if (dropdownOpen && activeIndex >= 0)
      document
        .getElementById(`${id}-option-${activeIndex}`)
        ?.scrollIntoView?.({ block: "nearest" });
  }, [activeIndex, dropdownOpen, id]);

  const changeOpen = (next: boolean) => {
    if (applying) return;
    setDropdownOpen(false);
    setActiveIndex(-1);
    setConfirmFailed(false);
    onOpenChange(next);
  };
  const select = (location: MapMenuLocation) => {
    onInputChange(location.label);
    onSelectLocation(location);
    inputRef.current?.focus();
    setDropdownOpen(false);
    setActiveIndex(-1);
  };
  const confirm = async () => {
    if (applying || !selectedLocation || !selectedMatchesInput) return;
    setApplying(true);
    setConfirmFailed(false);
    setDropdownOpen(false);
    try {
      if (props.mode === MapMenuMode.Point) {
        await props.onConfirm({ location: selectedLocation });
      } else {
        await props.onConfirm({
          location: selectedLocation,
          radiusKm: props.radiusKm,
        });
      }
      onOpenChange(false);
    } catch {
      setConfirmFailed(true);
    } finally {
      setApplying(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={changeOpen}>
      <DialogPortal>
        <DialogOverlay />
        <DialogPrimitive.Popup
          ref={popupRef}
          initialFocus={inputRef}
          aria-describedby={undefined}
          data-slot="map-menu"
          className={cn(
            "bg-muted text-foreground fixed top-[calc(var(--map-picker-top,0px)_+_var(--map-picker-height,100dvh)/2)] left-1/2 z-50 flex h-[var(--map-picker-height,100dvh)] w-screen max-w-none -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden border p-0 outline-none sm:h-[min(46.75rem,calc(var(--map-picker-height,100dvh)_-_5rem))] sm:w-[calc(100vw-4rem)] sm:max-w-[840px] sm:rounded-[10px] [@media(max-height:599px)]:h-[var(--map-picker-height,100dvh)]",
            className,
          )}
        >
          <DialogHeader className="shrink-0 px-5 pt-6 pr-16 pb-5 text-left sm:px-7 sm:pt-[25px] sm:pb-[22px] [@media(max-height:599px)]:py-4">
            <DialogTitle className="text-2xl font-semibold">{labels.title}</DialogTitle>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="absolute top-4 right-4 size-11"
              disabled={applying}
              aria-label={labels.close}
              onClick={() => changeOpen(false)}
            >
              <X />
            </Button>
          </DialogHeader>
          <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-[18px] overflow-y-auto px-5 pb-6 sm:px-7 [@media(max-height:599px)]:pb-3">
            <fieldset
              disabled={applying}
              data-slot="map-menu-toolbar"
              className={cn(
                "grid min-w-0 shrink-0 grid-cols-1 items-end gap-3",
                onUseCurrentLocation && "sm:grid-cols-[minmax(0,1fr)_max-content]",
              )}
            >
              <div
                className="relative flex min-w-0 flex-col gap-2"
                onBlur={(event) => {
                  if (!event.currentTarget.contains(event.relatedTarget)) setDropdownOpen(false);
                }}
              >
                <label htmlFor={`${id}-input`} className="text-sm font-medium">
                  {labels.location}
                </label>
                <div className="relative">
                  <Search
                    aria-hidden="true"
                    className="text-muted-foreground pointer-events-none absolute top-1/2 left-3.5 size-4 -translate-y-1/2"
                  />
                  <Input
                    ref={inputRef}
                    id={`${id}-input`}
                    value={input}
                    placeholder={labels.placeholder}
                    className="bg-card h-[50px] w-full rounded-md pr-11 pl-11 text-base"
                    autoComplete="off"
                    role="combobox"
                    aria-autocomplete="list"
                    aria-controls={`${id}-suggestions`}
                    aria-expanded={dropdownOpen}
                    aria-activedescendant={
                      dropdownOpen && suggestions[activeIndex]
                        ? `${id}-option-${activeIndex}`
                        : undefined
                    }
                    onFocus={() => {
                      if (input.trim() && !selectedMatchesInput) setDropdownOpen(true);
                    }}
                    onChange={(event) => {
                      onInputChange(event.currentTarget.value);
                      setActiveIndex(-1);
                      setConfirmFailed(false);
                      setDropdownOpen(Boolean(event.currentTarget.value.trim()));
                    }}
                    onKeyDown={(event) => {
                      if (event.key === "Escape" && dropdownOpen) {
                        event.preventDefault();
                        event.stopPropagation();
                        setDropdownOpen(false);
                      }
                      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                        event.preventDefault();
                        setDropdownOpen(true);
                        if (suggestions.length)
                          setActiveIndex((index) =>
                            index < 0
                              ? event.key === "ArrowDown"
                                ? 0
                                : suggestions.length - 1
                              : (index +
                                  (event.key === "ArrowDown" ? 1 : -1) +
                                  suggestions.length) %
                                suggestions.length,
                          );
                      }
                      if (event.key === "Enter" && dropdownOpen) {
                        event.preventDefault();
                        const location = suggestions[activeIndex];
                        if (location) select(location);
                      }
                    }}
                  />
                  {input ? (
                    <button
                      type="button"
                      aria-label={labels.clear}
                      className="text-muted-foreground absolute top-[3px] right-1 grid size-11 cursor-pointer place-items-center rounded focus-visible:outline-2 focus-visible:outline-offset-2"
                      onClick={() => {
                        onInputChange("");
                        setDropdownOpen(false);
                        setActiveIndex(-1);
                        inputRef.current?.focus();
                      }}
                    >
                      <X className="size-4" />
                    </button>
                  ) : null}
                </div>
                {dropdownOpen ? (
                  <div
                    id={`${id}-suggestions`}
                    role="listbox"
                    aria-label={labels.suggestions}
                    aria-busy={loadingSuggestions}
                    className="bg-popover text-popover-foreground absolute inset-x-0 top-full z-30 mt-1 max-h-[min(16rem,35dvh)] overflow-y-auto rounded-md border p-1 shadow-lg"
                  >
                    {suggestions.map((location, index) => (
                      <button
                        key={location.id}
                        id={`${id}-option-${index}`}
                        type="button"
                        role="option"
                        tabIndex={-1}
                        aria-label={location.label}
                        aria-selected={index === activeIndex}
                        className={cn(
                          "hover:bg-accent flex min-h-11 w-full items-center gap-3 rounded px-3 py-3 text-left",
                          index === activeIndex && "bg-accent",
                        )}
                        onMouseDown={(event) => event.preventDefault()}
                        onClick={() => select(location)}
                      >
                        <MapPin
                          aria-hidden="true"
                          className="size-4 shrink-0"
                          style={{ color: overlayColor }}
                        />
                        <span className="min-w-0">
                          <span className="block text-sm font-medium wrap-anywhere">
                            {location.title ?? location.label}
                          </span>
                          {location.details ? (
                            <span className="text-muted-foreground mt-1 block text-xs wrap-anywhere">
                              {location.details}
                            </span>
                          ) : null}
                        </span>
                      </button>
                    ))}
                    {loadingSuggestions ? (
                      <p role="status" className="text-muted-foreground p-3 text-sm">
                        {labels.loading}
                      </p>
                    ) : suggestionsError ? (
                      <p role="alert" className="text-destructive p-3 text-sm">
                        {suggestionsError}
                      </p>
                    ) : !suggestions.length ? (
                      <p className="text-muted-foreground p-3 text-sm">{labels.noResults}</p>
                    ) : null}
                  </div>
                ) : null}
              </div>
              {onUseCurrentLocation ? (
                <Button
                  type="button"
                  variant="outline"
                  data-slot="map-menu-current"
                  disabled={locating}
                  className="bg-card h-[50px] w-max gap-[7px] justify-self-start px-3 shadow-none"
                  onClick={onUseCurrentLocation}
                >
                  <LocateFixed className="text-foreground size-[17px]" />
                  {labels.currentLocation}
                </Button>
              ) : null}
              <div className="col-span-full grid text-xs leading-5">
                {[labels.ipNotice, labels.browserNotice, labels.searchHint].map((text) => (
                  <span
                    key={text}
                    aria-hidden="true"
                    className="invisible col-start-1 row-start-1 pl-6"
                  >
                    {text}
                  </span>
                ))}
                {notice ? (
                  <p
                    role="status"
                    data-slot="map-menu-provenance"
                    className="text-muted-foreground col-start-1 row-start-1 flex items-start gap-2"
                  >
                    <MapPin aria-hidden="true" className="text-foreground mt-0.5 size-4 shrink-0" />
                    <span className="wrap-anywhere">{notice}</span>
                  </p>
                ) : null}
              </div>
              {radiusEnabled ? (
                <div className="after:bg-border col-span-full flex flex-wrap items-center gap-3 after:h-px after:flex-1">
                  <label htmlFor={`${id}-radius`} className="text-sm font-medium">
                    {labels.searchWithin}
                  </label>
                  <div className="relative">
                    <select
                      id={`${id}-radius`}
                      value={radiusKm}
                      className="bg-card focus-visible:outline-ring h-11 appearance-none rounded border py-2 pr-9 pl-3 text-sm focus-visible:outline-2 focus-visible:outline-offset-2"
                      onChange={(event) => props.onRadiusChange(Number(event.currentTarget.value))}
                    >
                      {radiusOptions.map((radius) => (
                        <option key={radius} value={radius}>
                          {radius} km
                        </option>
                      ))}
                    </select>
                    <ChevronDown
                      aria-hidden="true"
                      className="pointer-events-none absolute top-1/2 right-3 size-4 -translate-y-1/2"
                    />
                  </div>
                </div>
              ) : null}
            </fieldset>
            <div
              data-slot="map-menu-map"
              className="relative min-h-56 min-w-0 flex-[1_0_14rem] [@media(max-height:599px)]:min-h-[182px] [@media(max-height:599px)]:basis-[182px]"
            >
              <MapMenuMap
                apiKey={apiKey}
                center={selectedLocation?.center ?? { lat: 0, lng: 0 }}
                zoom={!radiusEnabled && selectedLocation ? 15 : 4}
                marker={selectedLocation ? { icon: markerIcon } : undefined}
                radius={
                  radiusEnabled && selectedLocation && radiusKm !== undefined
                    ? {
                        radiusMeters: radiusKm * 1000,
                        fillColor: overlayColor,
                        fillOpacity: 0.12,
                        strokeColor: overlayColor,
                        strokeOpacity: 0.82,
                        strokeWeight: 2,
                      }
                    : undefined
                }
                fitRadius={radiusEnabled && Boolean(selectedLocation)}
                fitPadding={40}
                minZoom={3}
                maxZoom={18}
                locale={locale}
                className="h-full min-h-0 w-full rounded-md"
                controlsClassName="bg-card rounded-md shadow-md"
              />
              {radiusEnabled && selectedLocation ? (
                <p className="bg-card text-muted-foreground pointer-events-none absolute bottom-[25px] left-3 m-0 max-w-[calc(100%-24px)] rounded px-2.5 py-[7px] text-xs shadow-sm">
                  {labels.radiusHint}
                </p>
              ) : null}
            </div>
          </div>
          <DialogFooter className="shrink-0 gap-3 border-0 bg-transparent px-5 pt-[18px] pb-[max(18px,env(safe-area-inset-bottom))] sm:px-7 [@media(max-height:599px)]:pt-3 [@media(max-height:599px)]:pb-[max(12px,env(safe-area-inset-bottom))]">
            {error || confirmFailed ? (
              <p
                role="alert"
                className="text-destructive w-full self-center text-sm sm:mr-auto sm:w-auto"
              >
                {error ?? labels.confirmError}
              </p>
            ) : null}
            <div className="flex gap-2">
              <Button
                type="button"
                variant="outline"
                className="bg-card min-h-11 flex-1"
                disabled={applying}
                onClick={() => changeOpen(false)}
              >
                {labels.cancel}
              </Button>
              <Button
                type="button"
                data-slot="map-menu-confirm"
                className={cn(
                  "min-h-11 flex-[2] bg-[oklch(0.9247_0.0524_66.1732)] text-zinc-950 hover:bg-[oklch(0.9247_0.0524_66.1732)] hover:brightness-95",
                  confirmClassName,
                )}
                disabled={applying || !selectedMatchesInput || !selectedLocation}
                onClick={() => void confirm()}
              >
                {labels.confirm}
              </Button>
            </div>
          </DialogFooter>
        </DialogPrimitive.Popup>
      </DialogPortal>
    </Dialog>
  );
};

import { LocateFixed, Minus, Plus } from "lucide-react";
import { useEffect, useEffectEvent, useRef, useState, useSyncExternalStore } from "react";
import { Schema } from "effect";

import { cn } from "@/lib/utils";

import { useKrakstackLocale } from "@/components/ui/krakstack-provider";
export type GoogleMapPoint = {
  lat: number;
  lng: number;
};

export type GoogleMapMarkerOptions = {
  icon?: string | undefined;
};

export type GoogleMapRadiusOptions = {
  radiusMeters: number;
  fillColor?: string | undefined;
  fillOpacity?: number | undefined;
  strokeColor?: string | undefined;
  strokeOpacity?: number | undefined;
  strokeWeight?: number | undefined;
};

export type GoogleMapMessages = {
  mapLabel: string;
  loading: string;
  missingKeyTitle: string;
  missingKeyBody: string;
  errorTitle: string;
  errorBody: string;
  zoomIn: string;
  zoomOut: string;
  showArea: string;
};

export type GoogleMapMessageTranslations = Partial<Record<string, Partial<GoogleMapMessages>>>;

export type GoogleMapProps = {
  apiKey: string;
  center: GoogleMapPoint;
  zoom: number;
  marker?: boolean | GoogleMapMarkerOptions | undefined;
  radius?: GoogleMapRadiusOptions | undefined;
  interactive?: boolean | undefined;
  zoomControls?: boolean | undefined;
  fitRadius?: boolean | undefined;
  fitPadding?: number | undefined;
  minZoom?: number | undefined;
  maxZoom?: number | undefined;
  className?: string | undefined;
  controlsClassName?: string | undefined;
  messages?: GoogleMapMessageTranslations | undefined;
  locale?: string | undefined;
};

type GoogleMapOptions = {
  center: GoogleMapPoint;
  zoom: number;
  clickableIcons: boolean;
  disableDefaultUI: boolean;
  draggable: boolean;
  fullscreenControl: boolean;
  gestureHandling: "auto" | "none";
  keyboardShortcuts: boolean;
  mapTypeControl: boolean;
  maxZoom: number;
  minZoom: number;
  scrollwheel: boolean;
  streetViewControl: boolean;
  zoomControl: boolean;
};

type GoogleMapInstance = {
  fitBounds: (bounds: GoogleMapBounds, padding: number) => void;
  getZoom: () => number | undefined;
  setCenter: (center: GoogleMapPoint) => void;
  setOptions: (options: Partial<GoogleMapOptions>) => void;
  setZoom: (zoom: number) => void;
};

type GoogleMapBounds = {
  north: number;
  south: number;
  east: number;
  west: number;
};

type GoogleMarkerInstance = {
  setIcon: (icon?: string) => void;
  setMap: (map: GoogleMapInstance | null) => void;
  setPosition: (position: GoogleMapPoint) => void;
};

type GoogleCircleStyleOptions = Omit<GoogleMapRadiusOptions, "radiusMeters">;

type GoogleCircleInstance = {
  getBounds: () => { toJSON: () => GoogleMapBounds } | undefined;
  setCenter: (center: GoogleMapPoint) => void;
  setMap: (map: GoogleMapInstance | null) => void;
  setOptions: (options: GoogleCircleStyleOptions) => void;
  setRadius: (radiusMeters: number) => void;
};

type GoogleMapsEventListener = {
  remove: () => void;
};

type GoogleMapsEventTarget = GoogleMapInstance | GoogleMarkerInstance | GoogleCircleInstance;

export type GoogleMapsApi = {
  maps: {
    Map: new (element: HTMLElement, options: GoogleMapOptions) => GoogleMapInstance;
    Marker: new (options: {
      icon?: string | undefined;
      map: GoogleMapInstance;
      position: GoogleMapPoint;
    }) => GoogleMarkerInstance;
    Circle: new (
      options: GoogleCircleStyleOptions & {
        center: GoogleMapPoint;
        clickable: boolean;
        map: GoogleMapInstance;
        radius: number;
      },
    ) => GoogleCircleInstance;
    event: {
      addListener: (
        instance: GoogleMapsEventTarget,
        eventName: string,
        handler: () => void,
      ) => GoogleMapsEventListener;
      clearInstanceListeners: (instance: GoogleMapsEventTarget) => void;
    };
  };
};

type GoogleMapsWindow = Window & {
  google?: GoogleMapsApi | undefined;
  __krakStackGoogleMapsInit?: (() => void) | undefined;
};

type LoadState = "loading" | "ready" | "missing-key" | "error";

const googleMapsScriptId = "krak-stack-google-maps-script";
const googleMapsCallbackName = "__krakStackGoogleMapsInit";
let googleMapsPromise: Promise<GoogleMapsApi> | undefined;

const defaultMessages = {
  en: {
    mapLabel: "Google map",
    loading: "Loading map...",
    missingKeyTitle: "Map unavailable",
    missingKeyBody: "Provide a Google Maps API key to display the map.",
    errorTitle: "Map unavailable",
    errorBody: "Google Maps could not be loaded. Try again later.",
    zoomIn: "Zoom in",
    zoomOut: "Zoom out",
    showArea: "Show selected area",
  },
  fr: {
    mapLabel: "Carte Google",
    loading: "Chargement de la carte...",
    missingKeyTitle: "Carte indisponible",
    missingKeyBody: "Fournissez une clé d’API Google Maps pour afficher la carte.",
    errorTitle: "Carte indisponible",
    errorBody: "Impossible de charger Google Maps. Réessayez plus tard.",
    zoomIn: "Zoom avant",
    zoomOut: "Zoom arrière",
    showArea: "Afficher la zone sélectionnée",
  },
} as const satisfies Record<"en" | "fr", GoogleMapMessages>;

const googleMapMessages = (locale: string, translations?: GoogleMapMessageTranslations) => ({
  ...(locale.startsWith("fr") ? defaultMessages.fr : defaultMessages.en),
  ...translations?.[locale.split("-")[0] ?? locale],
  ...translations?.[locale],
});

const isGoogleMapsReady = (api: GoogleMapsApi | undefined): api is GoogleMapsApi =>
  Boolean(api?.maps.Map && api.maps.Marker && api.maps.Circle && api.maps.event);

const loadGoogleMaps = (apiKey: string) => {
  if (!globalThis.window || !globalThis.document) {
    return Promise.reject(new Error("Google Maps requires a browser."));
  }
  const browserWindow: GoogleMapsWindow = window;
  if (isGoogleMapsReady(browserWindow.google)) {
    return Promise.resolve(browserWindow.google);
  }
  if (googleMapsPromise) return googleMapsPromise;

  googleMapsPromise = new Promise<GoogleMapsApi>((resolve, reject) => {
    const resolveApi = () => {
      if (isGoogleMapsReady(browserWindow.google)) {
        resolve(browserWindow.google);
      } else reject(new Error("Google Maps failed to initialize."));
    };
    const rejectLoad = () => reject(new Error("Google Maps failed to load."));

    browserWindow.__krakStackGoogleMapsInit = resolveApi;

    const existingScript = document.getElementById(googleMapsScriptId);
    if (existingScript) {
      existingScript.addEventListener("error", rejectLoad, { once: true });
      existingScript.addEventListener("load", resolveApi, { once: true });
      return;
    }

    const script = document.createElement("script");
    script.id = googleMapsScriptId;
    script.async = true;
    script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(apiKey)}&loading=async&callback=${googleMapsCallbackName}`;
    script.addEventListener("error", rejectLoad, { once: true });
    document.head.append(script);
  }).catch((error) => {
    googleMapsPromise = undefined;
    browserWindow.__krakStackGoogleMapsInit = undefined;
    document.getElementById(googleMapsScriptId)?.remove();
    throw error;
  });

  return googleMapsPromise;
};

const clampZoom = (zoom: number, minZoom: number, maxZoom: number) =>
  Math.min(maxZoom, Math.max(minZoom, zoom));

const mapOptions = (
  center: GoogleMapPoint,
  zoom: number,
  interactive: boolean,
  minZoom: number,
  maxZoom: number,
): GoogleMapOptions => ({
  center,
  zoom: clampZoom(zoom, minZoom, maxZoom),
  clickableIcons: interactive,
  disableDefaultUI: true,
  draggable: interactive,
  fullscreenControl: false,
  gestureHandling: interactive ? "auto" : "none",
  keyboardShortcuts: interactive,
  mapTypeControl: false,
  maxZoom,
  minZoom,
  scrollwheel: interactive,
  streetViewControl: false,
  zoomControl: false,
});

// Google Maps owns this state; React reads a cached snapshot and subscribes to changes.
const createMapState = (loadState: LoadState, currentZoom: number) => {
  let snapshot = { loadState, currentZoom };
  const listeners = new Set<() => void>();
  const update = (next: typeof snapshot) => {
    if (next.loadState === snapshot.loadState && next.currentZoom === snapshot.currentZoom) return;
    snapshot = next;
    for (const listener of listeners) listener();
  };
  return {
    getSnapshot: () => snapshot,
    subscribe: (listener: () => void) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    setLoadState: (loadState: LoadState) => update({ ...snapshot, loadState }),
    setCurrentZoom: (currentZoom: number) => update({ ...snapshot, currentZoom }),
  };
};

/** Internal renderer shipped with MapMenu; not a standalone registry/package entry. */
export const MapMenuMap = ({
  apiKey,
  center,
  zoom,
  marker,
  radius,
  interactive = true,
  zoomControls = true,
  fitRadius = false,
  fitPadding = 32,
  minZoom = 3,
  maxZoom = 20,
  className,
  controlsClassName,
  messages: messageOverrides,
  locale: localeOverride,
}: GoogleMapProps) => {
  const locale = useKrakstackLocale(localeOverride);
  const mapElementRef = useRef<HTMLDivElement | null>(null);
  const apiRef = useRef<GoogleMapsApi | null>(null);
  const mapRef = useRef<GoogleMapInstance | null>(null);
  const markerRef = useRef<GoogleMarkerInstance | null>(null);
  const circleRef = useRef<GoogleCircleInstance | null>(null);
  const zoomListenerRef = useRef<GoogleMapsEventListener | null>(null);
  const normalizedApiKey = apiKey.trim();
  const normalizedMinZoom = Math.min(minZoom, maxZoom);
  const normalizedMaxZoom = Math.max(minZoom, maxZoom);
  const initialZoom = clampZoom(zoom, normalizedMinZoom, normalizedMaxZoom);
  const [mapState] = useState(() =>
    createMapState(normalizedApiKey ? "loading" : "missing-key", initialZoom),
  );
  const { loadState, currentZoom } = useSyncExternalStore(
    mapState.subscribe,
    mapState.getSnapshot,
    mapState.getSnapshot,
  );
  const { setLoadState, setCurrentZoom } = mapState;
  const labels = googleMapMessages(locale, messageOverrides);
  const markerOptions = Schema.is(Schema.Struct({ icon: Schema.optional(Schema.String) }))(marker)
    ? marker
    : undefined;
  const markerEnabled = marker === true || markerOptions !== undefined;
  const markerIcon = markerOptions?.icon;
  const centerLat = center.lat;
  const centerLng = center.lng;
  const radiusMeters = radius?.radiusMeters;
  const radiusFillColor = radius?.fillColor;
  const radiusFillOpacity = radius?.fillOpacity;
  const radiusStrokeColor = radius?.strokeColor;
  const radiusStrokeOpacity = radius?.strokeOpacity;
  const radiusStrokeWeight = radius?.strokeWeight;

  const showSelectedArea = () => {
    try {
      const element = mapElementRef.current;
      const bounds = circleRef.current?.getBounds()?.toJSON();
      if (!element?.clientWidth || !element.clientHeight || !bounds) return;
      mapRef.current?.fitBounds(bounds, Math.max(0, fitPadding));
    } catch {
      setLoadState("error");
    }
  };
  const fitSelection = useEffectEvent(showSelectedArea);

  const initializeMap = useEffectEvent((api: GoogleMapsApi, element: HTMLElement) => {
    const map = new api.maps.Map(
      element,
      mapOptions(center, zoom, interactive, normalizedMinZoom, normalizedMaxZoom),
    );
    apiRef.current = api;
    mapRef.current = map;
    zoomListenerRef.current = api.maps.event.addListener(map, "zoom_changed", () =>
      setCurrentZoom(map.getZoom() ?? zoom),
    );
    setCurrentZoom(clampZoom(zoom, normalizedMinZoom, normalizedMaxZoom));
    setLoadState("ready");
  });

  useEffect(() => {
    if (!normalizedApiKey) {
      setLoadState("missing-key");
      return;
    }

    const element = mapElementRef.current;
    if (!element) return;

    let mounted = true;
    setLoadState("loading");

    void loadGoogleMaps(normalizedApiKey)
      .then((api) => {
        if (!mounted) return;

        try {
          initializeMap(api, element);
        } catch {
          setLoadState("error");
        }
      })
      .catch(() => {
        if (mounted) setLoadState("error");
      });

    return () => {
      mounted = false;
      zoomListenerRef.current?.remove();
      markerRef.current?.setMap(null);
      circleRef.current?.setMap(null);
      if (mapRef.current) {
        apiRef.current?.maps.event.clearInstanceListeners(mapRef.current);
      }
      markerRef.current = null;
      circleRef.current = null;
      zoomListenerRef.current = null;
      mapRef.current = null;
      apiRef.current = null;
      element.replaceChildren();
    };
  }, [normalizedApiKey, setLoadState]);

  useEffect(() => {
    const map = mapRef.current;
    if (loadState !== "ready" || !map) return;
    const nextCenter = { lat: centerLat, lng: centerLng };
    const nextZoom = clampZoom(zoom, normalizedMinZoom, normalizedMaxZoom);
    try {
      map.setOptions(
        mapOptions(nextCenter, nextZoom, interactive, normalizedMinZoom, normalizedMaxZoom),
      );
      map.setCenter(nextCenter);
      map.setZoom(nextZoom);
      setCurrentZoom(nextZoom);
    } catch {
      setLoadState("error");
    }
  }, [
    centerLat,
    centerLng,
    zoom,
    interactive,
    fitRadius,
    normalizedMinZoom,
    normalizedMaxZoom,
    loadState,
    setLoadState,
    setCurrentZoom,
  ]);

  useEffect(() => {
    const api = apiRef.current;
    const map = mapRef.current;
    if (loadState !== "ready" || !api || !map) return;

    try {
      const nextCenter = { lat: centerLat, lng: centerLng };

      if (markerEnabled) {
        if (markerRef.current) {
          markerRef.current.setMap(map);
          markerRef.current.setPosition(nextCenter);
          markerRef.current.setIcon(markerIcon);
        } else {
          markerRef.current = new api.maps.Marker({
            icon: markerIcon,
            map,
            position: nextCenter,
          });
        }
      } else {
        markerRef.current?.setMap(null);
        markerRef.current = null;
      }

      if (radiusMeters !== undefined) {
        const style = {
          fillColor: radiusFillColor ?? "#18181b",
          fillOpacity: radiusFillOpacity ?? 0.12,
          strokeColor: radiusStrokeColor ?? "#18181b",
          strokeOpacity: radiusStrokeOpacity ?? 0.7,
          strokeWeight: radiusStrokeWeight ?? 2,
        };
        if (circleRef.current) {
          circleRef.current.setMap(map);
          circleRef.current.setCenter(nextCenter);
          circleRef.current.setRadius(radiusMeters);
          circleRef.current.setOptions(style);
        } else {
          circleRef.current = new api.maps.Circle({
            ...style,
            center: nextCenter,
            clickable: false,
            map,
            radius: radiusMeters,
          });
        }
      } else {
        circleRef.current?.setMap(null);
        circleRef.current = null;
      }
    } catch {
      setLoadState("error");
    }
  }, [
    centerLat,
    centerLng,
    loadState,
    markerEnabled,
    markerIcon,
    radiusFillColor,
    radiusFillOpacity,
    radiusMeters,
    radiusStrokeColor,
    radiusStrokeOpacity,
    radiusStrokeWeight,
    setLoadState,
  ]);

  useEffect(() => {
    const element = mapElementRef.current;
    if (loadState !== "ready" || !fitRadius || radiusMeters === undefined || !element) return;
    let frame = 0;
    const scheduleFit = () => {
      cancelAnimationFrame(frame);
      // Let Google paint updated overlay geometry before changing its projection.
      frame = requestAnimationFrame(() => {
        frame = requestAnimationFrame(() => fitSelection());
      });
    };
    scheduleFit();
    let width = element.clientWidth;
    let height = element.clientHeight;
    const observer = globalThis.ResizeObserver
      ? new ResizeObserver(() => {
          const nextWidth = element.clientWidth;
          const nextHeight = element.clientHeight;
          if (nextWidth === width && nextHeight === height) return;
          width = nextWidth;
          height = nextHeight;
          scheduleFit();
        })
      : undefined;
    observer?.observe(element);
    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
    };
  }, [
    loadState,
    fitRadius,
    fitPadding,
    interactive,
    centerLat,
    centerLng,
    radiusMeters,
    normalizedMinZoom,
    normalizedMaxZoom,
  ]);

  const changeZoom = (delta: number) => {
    const map = mapRef.current;
    if (!map) return;

    const nextZoom = clampZoom(
      (map.getZoom() ?? currentZoom) + delta,
      normalizedMinZoom,
      normalizedMaxZoom,
    );
    map.setZoom(nextZoom);
    setCurrentZoom(nextZoom);
  };

  return (
    <div
      data-slot="map-menu-renderer"
      className={cn(
        "bg-muted relative isolate min-h-64 min-w-0 overflow-hidden rounded-lg border",
        className,
      )}
    >
      <div
        ref={mapElementRef}
        data-slot="map-menu-canvas"
        className="h-full min-h-[inherit] w-full"
        role="region"
        aria-label={labels.mapLabel}
      />
      {loadState === "ready" && zoomControls ? (
        <div
          data-slot="map-menu-controls"
          className={cn(
            "bg-background/95 absolute top-3 right-3 z-10 overflow-hidden rounded-md border shadow-sm backdrop-blur",
            controlsClassName,
          )}
        >
          {fitRadius && radiusMeters !== undefined ? (
            <>
              <button
                data-slot="map-menu-control"
                type="button"
                onClick={showSelectedArea}
                aria-label={labels.showArea}
                title={labels.showArea}
                className="text-foreground hover:bg-accent focus-visible:ring-ring relative flex size-11 items-center justify-center focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset"
              >
                <LocateFixed className="size-4" />
              </button>
              <div className="bg-border h-px" />
            </>
          ) : null}
          <button
            data-slot="map-menu-control"
            type="button"
            className="text-foreground hover:bg-accent focus-visible:ring-ring relative flex size-11 items-center justify-center transition-colors focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset disabled:pointer-events-none disabled:opacity-50"
            disabled={currentZoom >= normalizedMaxZoom}
            onClick={() => changeZoom(1)}
            aria-label={labels.zoomIn}
          >
            <Plus className="size-4" />
          </button>
          <div className="bg-border h-px" />
          <button
            data-slot="map-menu-control"
            type="button"
            className="text-foreground hover:bg-accent focus-visible:ring-ring relative flex size-11 items-center justify-center transition-colors focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset disabled:pointer-events-none disabled:opacity-50"
            disabled={currentZoom <= normalizedMinZoom}
            onClick={() => changeZoom(-1)}
            aria-label={labels.zoomOut}
          >
            <Minus className="size-4" />
          </button>
        </div>
      ) : null}
      {loadState === "loading" ? (
        <div
          className="bg-background/75 text-muted-foreground absolute inset-0 grid place-items-center text-sm font-medium backdrop-blur-sm"
          role="status"
        >
          {labels.loading}
        </div>
      ) : null}
      {loadState === "missing-key" || loadState === "error" ? (
        <div className="bg-background/85 absolute inset-0 grid place-items-center p-6 text-center backdrop-blur-sm">
          <div
            className="bg-card text-card-foreground max-w-sm rounded-lg border p-5 shadow-sm"
            role="alert"
          >
            <p className="text-sm font-semibold">
              {loadState === "missing-key" ? labels.missingKeyTitle : labels.errorTitle}
            </p>
            <p className="text-muted-foreground mt-2 text-xs">
              {loadState === "missing-key" ? labels.missingKeyBody : labels.errorBody}
            </p>
          </div>
        </div>
      ) : null}
    </div>
  );
};

